assign round_cycle = (aes_state == AES_ST_ROUND_OP);
assign final_cycle = (aes_state == AES_ST_FINAL_ROUND);
assign done_cycle  = (aes_state == AES_ST_DONE);

assign cipher_busy = (aes_state == AES_ST_INIT_ROUND)  |
