// Next-state and round-counter sequencing.
// dcnt is loaded to 0xB for the initial round, then decremented once per cycle.
always @(aes_state or ld or dcnt) begin
    aes_state_next = aes_state;
    dcnt_next_mux = dcnt;

    case (aes_state)
        AES_ST_IDLE: begin
            dcnt_next_mux = 4'h0;
