        AES_ST_FINAL_ROUND: begin
            aes_state_next = AES_ST_DONE;
            if (dcnt > 4'h0) begin
                dcnt_next_mux = dcnt - 4'h1;
            end else begin
                dcnt_next_mux = 4'h0;
