        AES_ST_DONE: begin
            dcnt_next_mux = 4'h0;
            if (ld == 1'b1) begin
                aes_state_next = AES_ST_INIT_ROUND;
                dcnt_next_mux = 4'hb;
            end else begin
                aes_state_next = AES_ST_DONE;
